"""Exact Fraction checks for E10/E11/E04-local-constant/E14-Bbeta rational constants."""
from fractions import Fraction as F
import sympy as sp
R = []
def chk(n, c, *i):
    R.append(c); print(("PASS " if c else "FAIL ") + n, *i)
z = sp.symbols('z')
chk("E10 P(z)^2-(1-z)=z^3/8+z^4/64", sp.expand((1-z/2-z**2/8)**2-(1-z)-(z**3/8+z**4/64)) == 0)
t = sp.symbols('t')
chk("E10 int_0^1 P(t^4) dt = 319/360", sp.integrate(1-t**4/2-t**8/8, (t, 0, 1)) == sp.Rational(319, 360))
chk("E10 a>=15/16>(29/30)^2", F(15, 16) > F(29, 30)**2)
k = F(4)*F(319, 360)
chk("E10 kappa/sqrt a half: (4*319/360)/(29/30)=319/87 ; *20/197=6380/17139<3/8", k/F(29, 30) == F(319, 87) and F(319, 87)*F(20, 197) == F(6380, 17139) and 6380*8 == 51040 and 3*17139 == 51417 and F(6380, 17139) < F(3, 8))
chk("E10 kappa/sqrt a rho1: /(7/8) = 1276/315 ; *20/197 = 25520/62055 < 5/12", k/F(7, 8) == F(1276, 315) and F(1276, 315)*F(20, 197) == F(25520, 62055) and F(25520, 62055) < F(5, 12))
chk("E10 1/(a pi^2): half 16*20/(15*197)<1/9 ; rho1 64*20/(49*197)<2/15 (19200<19306)", F(320, 2955) < F(1, 9) and F(1280, 9653) < F(2, 15) and 1280*15 == 19200 and 2*9653 == 19306)
chk("E10 (6) coefficient conversions", F(1, 9)*F(3, 2) == F(1, 6) and F(1, 9)*F(3, 4) == F(1, 12) and F(2, 15)*F(3, 2) == F(1, 5) and F(2, 15)*F(3, 4) == F(1, 10))
chk("E10 cos(1/2)>=7/8 via 1-1/8+1/384 lower Taylor", F(1)-F(1, 8)+F(1, 384)-F(1, 46080) > F(7, 8))
chk("E11-5/4 ce>=1-(5/8)^2/2=103/128 ; a>=10609/16384 ; v/a<=8192/10609<1", F(1)-F(25, 64)/2 == F(103, 128) and F(103, 128)**2 == F(10609, 16384) and F(1, 2)/F(10609, 16384) == F(8192, 10609))
v = k/F(103, 128)*F(20, 197)
chk("E11-5/4 kappa/sqrt a < 9/20", v < F(9, 20), float(v))
chk("E14-halfnear Bbeta coefficient (23/24)(69/100+3/2)/10 = 5037/24000 = 1679/8000 > 1/5", F(23, 24)*(F(69, 100)+F(3, 2))/10 == F(5037, 24000) == F(1679, 8000) and F(1679, 8000) > F(1, 5))
b = sp.symbols('b', positive=True); e = sp.symbols('e', positive=True)
chk("E14-halfnear int_0^b (1-e/b)(-log e) de = (b/2)(3/2+log(1/b))", sp.simplify(sp.integrate((1-e/b)*(-sp.log(e)), (e, 0, b)) - (b/2)*(sp.Rational(3, 2)-sp.log(b))) == 0)
chk("E04-lc BOX: 6(7/8)(2-2/7)=9; Af<16(9/10)/(3)*20/197=96/197<1/2", F(6)*F(7, 8)*(2-F(2, 7)) == 9 and F(16)*F(9, 10)/3*F(20, 197) == F(96, 197) < F(1, 2))
chk("E04-lc BOX hx<640/1379<7/15, hy<160/1379<7/60", F(4)*F(8, 7)*F(20, 197) == F(640, 1379) < F(7, 15) and F(8, 7)*F(20, 197) == F(160, 1379) < F(7, 60))
tau = F(7, 16)/F(207, 256)
chk("E04-lc r<=7/8: tau=112/207, 6a(2-tau)=453/64>(21/8)^2", tau == F(112, 207) and 6*F(207, 256)*(2-tau) == F(453, 64) and F(453, 64) > F(21, 8)**2)
chk("E04-lc r<=7/8 Af<768/1379<9/16, hx<20480/40779<51/100, hy<5120/40779<51/400", F(16)*F(9, 10)/F(21, 8)*F(20, 197) == F(768, 1379) < F(9, 16) and 4*F(256, 207)*F(20, 197) == F(20480, 40779) < F(51, 100) and F(256, 207)*F(20, 197) == F(5120, 40779) < F(51, 400))
chk("E04-lc table", F(1, 2)+F(3, 4)*F(7, 15) == F(17, 20) and F(3, 4)*F(7, 60) == F(7, 80) and F(19, 24)+F(7, 15) == F(151, 120) and F(19, 24)+F(3, 2)*F(7, 60) == F(29, 30) and F(9, 16)+F(3, 4)*F(51, 100) == F(189, 200) and F(3, 4)*F(51, 400) == F(153, 1600) and F(19, 24)+F(51, 100) == F(781, 600) and F(19, 24)+F(3, 2)*F(51, 400) == F(2359, 2400))
chk("E05 csc^2 constant (15/28)^2=225/784<1/3", (F(3)/(2*(3-F(1, 5))))**2 == F(225, 784) and F(225, 784) < F(1, 3))
chk("E05 (11) 256/225<=6/5 ; 48/(5pi)<16/5 for pi>3", F(256, 225) <= F(6, 5) and F(48, 15) <= F(16, 5))
print("SUMMARY", sum(R), "/", len(R))
